import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.Crpw6aS5.js";const i="/assets/og-preview.Cx9YlU2H.png",r="/assets/01-standard-rag.D2PRG1QD.png",s="/assets/02-contextual-retrieval-preprocessing.CacfRkDv.png",l="/assets/03-performance-contextual-embeddings-bm25.D0zoHtn4.png",c="/assets/04-reranking-pipeline.WpSKdZ-o.png",d="/assets/05-performance-reranking.DHMcblow.png",p="/assets/06-appendix-results-recall-at-20.DWQ2GdLk.png",v=JSON.parse(`{"title":"Contextual Retrieval (Anthropic)","description":"Imported notes from Anthropic's engineering post on Contextual Embeddings and Contextual BM25 for improved RAG retrieval.","frontmatter":{"title":"Contextual Retrieval (Anthropic)","description":"Imported notes from Anthropic's engineering post on Contextual Embeddings and Contextual BM25 for improved RAG retrieval."},"headers":[],"relativePath":"misc/artificial-intelligence/anthropic-contextual-retrieval.md","filePath":"misc/artificial-intelligence/anthropic-contextual-retrieval.md"}`),u={name:"misc/artificial-intelligence/anthropic-contextual-retrieval.md"};function h(m,e,g,b,k,f){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="introducing-contextual-retrieval" tabindex="-1">Introducing Contextual Retrieval <a class="header-anchor" href="#introducing-contextual-retrieval" aria-label="Permalink to &quot;Introducing Contextual Retrieval&quot;">​</a></h1><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage</li><li>Origin: <a href="https://www.anthropic.com/engineering/contextual-retrieval" target="_blank" rel="noreferrer">https://www.anthropic.com/engineering/contextual-retrieval</a></li><li>Imported: 2025-08-30</li><li>Published: September 19, 2024</li><li>Cookbook: <a href="https://platform.claude.com/cookbook/capabilities-contextual-embeddings-guide" target="_blank" rel="noreferrer">Claude Cookbook — contextual embeddings</a></li><li>Images: 7 diagrams/charts saved under <code>./assets/anthropic-contextual-retrieval/</code></li></ul><p><img src="'+i+'" alt="Contextual Retrieval — Anthropic engineering preview"></p><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p>For an AI model to be useful in specific contexts, it often needs access to background knowledge — customer support chatbots need business-specific information, legal analyst bots need past cases, and so on.</p><p>Developers typically enhance model knowledge with <strong>Retrieval-Augmented Generation (RAG)</strong>. RAG retrieves relevant information from a knowledge base and appends it to the user&#39;s prompt. The problem: traditional RAG solutions remove context when encoding information, often causing the system to fail to retrieve the relevant chunks.</p><p><strong>Contextual Retrieval</strong> dramatically improves the retrieval step using two sub-techniques:</p><ul><li><strong>Contextual Embeddings</strong> — prepend chunk-specific explanatory context before embedding</li><li><strong>Contextual BM25</strong> — index both raw chunk content and generated context for keyword search</li></ul><p>Results: <strong>49% reduction</strong> in failed retrievals (Contextual Embeddings + Contextual BM25), and <strong>67% reduction</strong> when combined with reranking.</p><h3 id="a-note-on-simply-using-a-longer-prompt" tabindex="-1">A note on simply using a longer prompt <a class="header-anchor" href="#a-note-on-simply-using-a-longer-prompt" aria-label="Permalink to &quot;A note on simply using a longer prompt&quot;">​</a></h3><p>If your knowledge base is smaller than 200,000 tokens (~500 pages), you can include the entire knowledge base in the prompt with no RAG. <a href="https://platform.claude.com/cookbook/misc-prompt-caching" target="_blank" rel="noreferrer">Prompt caching</a> makes this faster and cheaper — reducing latency by &gt;2x and costs by up to 90%.</p><p>As your knowledge base grows, you need a more scalable solution. That&#39;s where Contextual Retrieval comes in.</p><h3 id="a-primer-on-rag" tabindex="-1">A primer on RAG <a class="header-anchor" href="#a-primer-on-rag" aria-label="Permalink to &quot;A primer on RAG&quot;">​</a></h3><p>For knowledge bases that don&#39;t fit in the context window, RAG preprocesses documents:</p><ol><li>Break the corpus into smaller chunks (usually a few hundred tokens)</li><li>Convert chunks to vector embeddings encoding meaning</li><li>Store embeddings in a vector database for semantic similarity search</li></ol><p>At runtime, the vector database finds the most relevant chunks, which are added to the generative model&#39;s prompt.</p><h4 id="bm25-and-hybrid-search" tabindex="-1">BM25 and hybrid search <a class="header-anchor" href="#bm25-and-hybrid-search" aria-label="Permalink to &quot;BM25 and hybrid search&quot;">​</a></h4><p>Embedding models excel at semantic relationships but can miss exact matches. <strong>BM25 (Best Matching 25)</strong> uses lexical matching to find precise word or phrase matches — effective for unique identifiers or technical terms.</p><p>BM25 builds on TF-IDF, refining it by considering document length and applying a saturation function to term frequency.</p><p><strong>Example:</strong> A query for &quot;Error code TS-999&quot; — embeddings might find general error code content but miss the exact match; BM25 looks for that specific string.</p><p>Hybrid RAG combines embeddings and BM25:</p><ol><li>Break corpus into chunks</li><li>Create TF-IDF encodings and semantic embeddings</li><li>Use BM25 for top chunks by exact match</li><li>Use embeddings for top chunks by semantic similarity</li><li>Combine and deduplicate via rank fusion</li><li>Add top-K chunks to the prompt</li></ol><p><img src="'+r+`" alt="Standard RAG system using embeddings and BM25"></p><p>This scales to enormous knowledge bases but has a significant limitation: <strong>it often destroys context</strong>.</p><h3 id="the-context-conundrum-in-traditional-rag" tabindex="-1">The context conundrum in traditional RAG <a class="header-anchor" href="#the-context-conundrum-in-traditional-rag" aria-label="Permalink to &quot;The context conundrum in traditional RAG&quot;">​</a></h3><p>When documents are split into smaller chunks, individual chunks can lack sufficient context.</p><p><strong>Example:</strong> A collection of U.S. SEC filings, query: &quot;What was the revenue growth for ACME Corp in Q2 2023?&quot;</p><p>A relevant chunk might say: <em>&quot;The company&#39;s revenue grew by 3% over the previous quarter.&quot;</em> Without knowing which company or time period, this chunk is hard to retrieve or use effectively.</p><h3 id="introducing-contextual-retrieval-1" tabindex="-1">Introducing Contextual Retrieval <a class="header-anchor" href="#introducing-contextual-retrieval-1" aria-label="Permalink to &quot;Introducing Contextual Retrieval&quot;">​</a></h3><p>Contextual Retrieval prepends chunk-specific explanatory context to each chunk before embedding (<strong>Contextual Embeddings</strong>) and before creating the BM25 index (<strong>Contextual BM25</strong>).</p><p><strong>SEC filing example:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>original_chunk = &quot;The company&#39;s revenue grew by 3% over the previous quarter.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>contextualized_chunk = &quot;This chunk is from an SEC filing on ACME corp&#39;s performance in Q2 2023; the previous quarter&#39;s revenue was $314 million. The company&#39;s revenue grew by 3% over the previous quarter.&quot;</span></span></code></pre></div><p>Other context-based approaches were evaluated with limited gains: generic document summaries, hypothetical document embedding, and summary-based indexing.</p><h3 id="implementing-contextual-retrieval" tabindex="-1">Implementing Contextual Retrieval <a class="header-anchor" href="#implementing-contextual-retrieval" aria-label="Permalink to &quot;Implementing Contextual Retrieval&quot;">​</a></h3><p>Manual annotation of thousands of chunks is impractical. Anthropic uses Claude to generate concise, chunk-specific context explaining each chunk within its document:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;document&gt;</span></span>
<span class="line"><span>{{WHOLE_DOCUMENT}}</span></span>
<span class="line"><span>&lt;/document&gt;</span></span>
<span class="line"><span>Here is the chunk we want to situate within the whole document</span></span>
<span class="line"><span>&lt;chunk&gt;</span></span>
<span class="line"><span>{{CHUNK_CONTENT}}</span></span>
<span class="line"><span>&lt;/chunk&gt;</span></span>
<span class="line"><span>Please give a short succinct context to situate this chunk within the overall document</span></span>
<span class="line"><span>for the purposes of improving search retrieval of the chunk.</span></span>
<span class="line"><span>Answer only with the succinct context and nothing else.</span></span></code></pre></div><p>The resulting contextual text (typically 50–100 tokens) is prepended to the chunk before embedding and before creating the BM25 index.</p><p><img src="`+s+'" alt="Contextual Retrieval preprocessing flow"></p><h3 id="using-prompt-caching-to-reduce-costs" tabindex="-1">Using prompt caching to reduce costs <a class="header-anchor" href="#using-prompt-caching-to-reduce-costs" aria-label="Permalink to &quot;Using prompt caching to reduce costs&quot;">​</a></h3><p>Contextual Retrieval is uniquely practical at low cost with Claude thanks to prompt caching. Load the reference document into cache once, then reference cached content for each chunk.</p><p><strong>Cost example</strong> (800-token chunks, 8k-token documents, 50-token context instructions, 100 tokens of context per chunk): <strong>$1.02 per million document tokens</strong> one-time.</p><h4 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h4><p>Experiments across knowledge domains (codebases, fiction, ArXiv papers, science papers), embedding models, retrieval strategies, and evaluation metrics. Evaluation metric: <strong>1 minus recall@20</strong> — percentage of relevant documents failing to be retrieved in the top 20 chunks. Top-performing embedding: Gemini Text 004; retrieving top-20 chunks.</p><h4 id="performance-improvements" tabindex="-1">Performance improvements <a class="header-anchor" href="#performance-improvements" aria-label="Permalink to &quot;Performance improvements&quot;">​</a></h4><ul><li><strong>Contextual Embeddings</strong> reduced top-20-chunk retrieval failure rate by <strong>35%</strong> (5.7% → 3.7%)</li><li><strong>Contextual Embeddings + Contextual BM25</strong> reduced failure rate by <strong>49%</strong> (5.7% → 2.9%)</li></ul><p><img src="'+l+'" alt="Contextual Embedding and Contextual BM25 reduce retrieval failure rate by 49%"></p><h4 id="implementation-considerations" tabindex="-1">Implementation considerations <a class="header-anchor" href="#implementation-considerations" aria-label="Permalink to &quot;Implementation considerations&quot;">​</a></h4><ol><li><strong>Chunk boundaries</strong> — chunk size, boundary, and overlap affect retrieval performance</li><li><strong>Embedding model</strong> — contextual retrieval improves all tested models; Gemini and Voyage embeddings were particularly effective</li><li><strong>Custom contextualizer prompts</strong> — domain-specific prompts (e.g. including a glossary) may outperform the generic prompt</li><li><strong>Number of chunks</strong> — more chunks increase recall but can distract the model; top-20 outperformed top-5 and top-10 in experiments</li></ol><p>Always run evals. Response generation may improve by passing the contextualized chunk and distinguishing context from chunk content.</p><h3 id="further-boosting-performance-with-reranking" tabindex="-1">Further boosting performance with reranking <a class="header-anchor" href="#further-boosting-performance-with-reranking" aria-label="Permalink to &quot;Further boosting performance with reranking&quot;">​</a></h3><p>With large knowledge bases, initial retrieval can return hundreds of chunks of varying relevance. <strong>Reranking</strong> filters to only the most relevant chunks:</p><ol><li>Initial retrieval for top potentially relevant chunks (top 150)</li><li>Pass top-N chunks and user query through reranking model</li><li>Score each chunk by relevance; select top-K (top 20)</li><li>Pass top-K chunks to the model as context</li></ol><p><img src="'+c+'" alt="Combine Contextual Retrieval and reranking to maximize retrieval accuracy"></p><p>Tests used the Cohere reranker (Voyage also offers one, untested).</p><p><strong>Reranked Contextual Embedding + Contextual BM25</strong> reduced top-20-chunk retrieval failure rate by <strong>67%</strong> (5.7% → 1.9%).</p><p><img src="'+d+'" alt="Reranked Contextual Embedding and Contextual BM25 reduce failure rate by 67%"></p><p><strong>Cost and latency:</strong> Reranking adds runtime latency (reranker scores chunks in parallel). Trade-off between reranking more chunks for better performance vs. fewer for lower latency and cost.</p><h3 id="conclusion-—-what-stacks" tabindex="-1">Conclusion — what stacks <a class="header-anchor" href="#conclusion-—-what-stacks" aria-label="Permalink to &quot;Conclusion — what stacks&quot;">​</a></h3><ol><li>Embeddings + BM25 is better than embeddings alone</li><li>Voyage and Gemini had the best embeddings tested</li><li>Passing top-20 chunks is more effective than top-10 or top-5</li><li>Adding context to chunks improves retrieval accuracy significantly</li><li>Reranking is better than no reranking</li><li>Benefits stack: contextual embeddings (Voyage or Gemini) + contextual BM25 + reranking + top-20 chunks</li></ol><h3 id="appendix-i" tabindex="-1">Appendix I <a class="header-anchor" href="#appendix-i" aria-label="Permalink to &quot;Appendix I&quot;">​</a></h3><p>Breakdown of results across datasets, embedding providers, BM25, contextual retrieval, and reranking for Retrievals @ 20.</p><p><img src="'+p+'" alt="1 minus recall @ 20 results across datasets and embedding providers"></p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>Traditional RAG loses context when chunking documents — isolated chunks fail retrieval even when semantically related to the query.</li><li>Contextual Retrieval uses Claude to generate 50–100 token situating context per chunk, prepended before embedding and BM25 indexing.</li><li>Prompt caching makes contextualization affordable at scale (~$1.02 per million document tokens one-time).</li><li>Contextual Embeddings alone cut retrieval failures by 35%; adding Contextual BM25 reaches 49%; adding reranking reaches 67%.</li><li>For small knowledge bases (&lt;200k tokens), full prompt inclusion with caching may be simpler than RAG.</li><li>Gemini and Voyage embeddings performed best in Anthropic&#39;s tests; top-20 chunks outperformed smaller K values.</li><li>See the <a href="https://platform.claude.com/cookbook/capabilities-contextual-embeddings-guide" target="_blank" rel="noreferrer">Claude Cookbook</a> for a hands-on implementation.</li></ul>',65)])])}const y=t(u,[["render",h]]);export{v as __pageData,y as default};
